const p = $('Fälligen Instagram-Post holen').first().json;
// Dateien im Themenordner (SPEICHER 1): Ordner Instagram-Post und Instagram-Story aufgelistet, Caption geholt
const L = $('Ordner lesen (SPEICHER 1)').all().map(i => i.json);
const ort = (L[0] && L[0].ort) || 'Speicherort';
const namen = e => (e && e.ok === true && Array.isArray(e.eintraege) ? e.eintraege : []).filter(x => !x.ordner).map(x => String(x.name || ''));
const listeFehler = (L.find(e => e.ok !== true) || {}).fehler || '';
const cap = $input.first();
let capDatei = '';
if (cap && cap.json && cap.json.ok === true && cap.binary && cap.binary.datei) {
  try { capDatei = (await this.helpers.getBinaryDataBuffer(0, 'datei')).toString('utf8').replace(/^﻿/, '').trim(); } catch (e) { capDatei = ''; }
}
const capNichtLesbar = namen(L[0]).includes('caption.txt') && !(cap && cap.json && cap.json.ok === true);
let paket = {};
try { paket = typeof p.paket === 'string' ? JSON.parse(p.paket) : (p.paket || {}); } catch (e) { paket = {}; }
let caption = capDatei;
if (!caption) caption = (String(paket.instagram_caption || '').trim() + '\n\n' + (Array.isArray(paket.instagram_hashtags) ? paket.instagram_hashtags.join(' ') : '')).trim();
const posts = namen(L[0]).filter(f => /^karussell-[0-9]+\.jpg$/.test(f)).sort().map(f => 'Instagram-Post/' + f);
const stories = namen(L[1]).filter(f => /^story-[0-9]+\.jpg$/.test(f)).sort().map(f => 'Instagram-Story/' + f);
// Öffentliche n8n-Adresse aus ally_einstellungen (n8n_oeffentlich), damit Instagram die Bilder abrufen kann (Stefan 17.10.2026)
const oeffentlich = String(p.n8n_oeffentlich || '').trim().replace(/\/+$/, '');
const basis = oeffentlich + '/webhook/ally-medien?p=' + p.post_id + '&k=' + p.medien_token + '&d=';
const url = rel => basis + encodeURIComponent(rel);
const gemein = { post_id: p.post_id, titel: p.titel, kanal: p.kanal, format: p.format, room_id: p.room_id, matrix_user_id: p.matrix_user_id, ig_id: p.ig_id, token: p.ig_token };

let fehler = '';
let bilder = [];
// Instagram ist ein Firmenzugang (ally_einstellungen), Hinterlegen in der Ally-Oberfläche (Stefan 17.10.2026)
// Produktname aus der Datenbank (Fälligen Instagram-Post holen) statt fest im Code (Stefan 18.10.2026)
const produkt = String(p.produkt_name || '').trim();
const oberflaeche = produkt ? produkt + '-Oberfläche' : 'Oberfläche';
if (!p.ig_token || !p.ig_id) fehler = 'Instagram ist nicht verbunden. Zugang hinterlegen unter ' + oberflaeche + ' › Marketing › Veröffentlichen › Instagram-Zugang.';
else if (!oeffentlich) fehler = 'Die öffentliche n8n-Adresse (Einstellung n8n_oeffentlich) ist nicht hinterlegt. Ohne sie kann Instagram die Bilder nicht abrufen.';
else if (listeFehler) fehler = 'Der Themenordner im Speicherort (' + ort + ') konnte nicht gelesen werden: ' + listeFehler;
else if (p.kanal === 'instagram_story') {
  bilder = stories;
  if (!bilder.length) fehler = 'Keine Story-Bilder (JPG) im Ordner Instagram-Story gefunden – bitte das Paket neu erstellen lassen.';
} else {
  bilder = p.format === 'bild' ? posts.slice(0, 1) : posts.slice(0, 10);
  const ph = caption.match(/\[[^\]\n]{2,}\]/);
  const tags = (caption.match(/#[\p{L}\p{N}_]+/gu) || []).length;
  if (!bilder.length) fehler = 'Keine Beitragsbilder (JPG) im Ordner Instagram-Post gefunden – bitte das Paket neu erstellen lassen.';
  else if (capNichtLesbar) fehler = 'Die Datei Instagram-Post/caption.txt konnte nicht gelesen werden: ' + ((cap && cap.json && cap.json.fehler) || 'unbekannter Fehler');
  else if (!caption) fehler = 'Keine Caption gefunden (Instagram-Post/caption.txt).';
  else if (ph) fehler = 'In der Caption steht noch ein Platzhalter in eckigen Klammern: ' + ph[0] + ' – bitte in Instagram-Post/caption.txt ersetzen und dann erneut freigeben.';
  else if (caption.length > 2200) fehler = 'Die Caption ist mit ' + caption.length + ' Zeichen länger als die 2.200 Zeichen, die Instagram erlaubt.';
  else if (tags > 30) fehler = 'Die Caption enthält ' + tags + ' Hashtags, Instagram erlaubt höchstens 30.';
}
if (fehler) return [{ json: Object.assign({}, gemein, { bereit: false, fehler }) }];

// Nur ein Bild vorhanden -> als normaler Einzelbild-Beitrag posten (Karussell braucht mindestens 2)
const karussell = p.kanal === 'instagram_post' && p.format !== 'bild' && bilder.length > 1;
return bilder.map((rel, i) => ({ json: Object.assign({}, gemein, {
  bereit: true, fehler: '', nr: i + 1, datei: rel, image_url: url(rel),
  karussell, caption: karussell ? caption : '',
  felder: Object.assign({ image_url: url(rel), access_token: p.ig_token },
    karussell ? { is_carousel_item: 'true' } : {},
    p.kanal === 'instagram_story' ? { media_type: 'STORIES' } : {},
    (!karussell && p.kanal === 'instagram_post') ? { caption } : {})
}) }));

const items = $input.all().map(i => i.json);
const plan = $('Plan erstellen').all().map(i => i.json);
const fehlerhaft = items.map((r, i) => ({ r, i })).filter(x => !(x.r.statusCode === 200 && x.r.body && x.r.body.id));
const msg = r => (r && r.body && r.body.error && (r.body.error.error_user_msg || r.body.error.message)) || (r && r.error && (r.error.message || r.error)) || ('Status ' + (r && r.statusCode));
if (fehlerhaft.length) {
  const x = fehlerhaft[0];
  return [{ json: { container_ok: false, fehler: 'Instagram hat Bild ' + (x.i + 1) + ' (' + ((plan[x.i] || {}).datei || '?') + ') nicht angenommen: ' + msg(x.r) } }];
}
const g = plan[0];
const ids = items.map(r => r.body.id);
if (g.karussell) return [{ json: { container_ok: true, karussell: true, children: ids.join(','), caption: g.caption, ig_id: g.ig_id, token: g.token } }];
return ids.map(id => ({ json: { container_ok: true, karussell: false, creation_id: id, ig_id: g.ig_id, token: g.token } }));

const s = $('Container sammeln').first().json;
const r = $input.first().json;
return [{ json: { creation_id: (r.body && r.body.id) || '', ig_id: s.ig_id, token: s.token } }];

// Chat-Layout (Vorgabe Stefan, 11.10.2026): Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, keine Listenpunkte, keine Emojis
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : (z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)));
const zeileText = z => typeof z === 'string' ? roh(z) : (z.behalten ? String(z.t ?? '') : roh(z.t));
const render = bloecke => {
  const b = bloecke.filter(x => x).map(x => Object.assign({}, x, { zeilen: (x.zeilen || []).filter(z => z !== undefined && z !== null && z !== '') })).filter(x => x.titel || x.zeilen.length);
  return {
    html: b.map(x => (x.titel ? '<strong>' + esc(x.titel) + '</strong>' + ((x.zeilen || []).length ? '<br>' : '') : '') + (x.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: b.map(x => (x.titel ? roh(x.titel) + ((x.zeilen || []).length ? '\n' : '') : '') + (x.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
const p = $('Fälligen Instagram-Post holen').first().json;
const plan0 = $('Plan erstellen').first().json;
const msg = r => (r && r.body && r.body.error && (r.body.error.error_user_msg || r.body.error.message)) || (r && r.error && (r.error.message || r.error)) || ('Status ' + (r && r.statusCode));
let fehler = plan0.fehler || '';
const links = [];
let veroeffentlicht = 0;
if (!fehler && $('Container sammeln').isExecuted) {
  const s = $('Container sammeln').first().json;
  if (s.container_ok === false) fehler = s.fehler;
}
if (!fehler && $('Karussell-Container anlegen').isExecuted) {
  const k = $('Karussell-Container anlegen').first().json;
  if (!(k.statusCode === 200 && k.body && k.body.id)) fehler = 'Instagram hat das Karussell nicht angenommen: ' + msg(k);
}
if (!fehler) {
  const pub = $('Veröffentlichen').isExecuted ? $('Veröffentlichen').all().map(i => i.json) : [];
  const lk = $('Link holen').isExecuted ? $('Link holen').all().map(i => i.json) : [];
  pub.forEach((r, i) => {
    if (r.statusCode === 200 && r.body && r.body.id) { veroeffentlicht++; const l = lk[i] && lk[i].body && lk[i].body.permalink; if (l) links.push(l); }
  });
  if (!pub.length) fehler = 'Es wurde nichts veröffentlicht.';
  else if (veroeffentlicht < pub.length) {
    const r = pub.find(x => !(x.statusCode === 200 && x.body && x.body.id));
    fehler = (veroeffentlicht ? veroeffentlicht + ' von ' + pub.length + ' Storys veröffentlicht, Rest abgelehnt: ' : 'Instagram hat die Veröffentlichung abgelehnt: ') + msg(r);
  }
}
const art = p.kanal === 'instagram_story' ? 'Instagram-Story' : (p.format === 'bild' ? 'Instagram-Beitrag' : 'Instagram-Karussell');
const ok = !fehler;
const teil = !ok && veroeffentlicht > 0;
const status = ok || teil ? 'gepostet' : 'fehler';
const url = links[0] || (veroeffentlicht ? 'https://www.instagram.com/' + (p.ig_username || '') : '');
const link = url ? [{ t: url, html: '<a href="' + esc(url) + '">' + esc(url) + '</a>' }] : [];
const n = ok
  ? render([{ titel: art + ' veröffentlicht:', zeilen: [p.titel].concat(link) }])
  : render([{ titel: art + ' nicht (vollständig) veröffentlicht:', zeilen: [p.titel].concat(link) }, { titel: 'Grund:', zeilen: [fehler] }, teil ? null : { zeilen: ['Der Auftrag steht auf „Fehler“. Nach der Korrektur einfach erneut freigeben.'] }]);
return [{ json: { post_id: p.post_id, status, post_url: url, fehler, room_id: p.room_id, matrix_user_id: p.matrix_user_id, text: n.text, html: n.html } }];

// Ordner vorbereiten: Bilder des Themas im Speicherort auflisten (Aufträge an SPEICHER 1)
const o = $('Fälligen Instagram-Post holen').first().json.ordner || '_';
return ['Instagram-Post', 'Instagram-Story'].map(u => ({ json: { aktion: 'liste', bereich: 'ally', pfad: o + '/' + u } }));

// Caption vorbereiten: Caption des Beitrags aus dem Speicherort holen (Auftrag an SPEICHER 1)
const o = $('Fälligen Instagram-Post holen').first().json.ordner || '_';
return [{ json: { aktion: 'holen', bereich: 'ally', pfad: o + '/Instagram-Post/caption.txt' } }];

